"""Background, non-blocking session titles generated by the local model.

Title generation never runs on the chat path: a background worker submits a
short non-streaming completion after the first reply is stored, waits until the
model is idle, and writes the result straight to the session store. The TUI
picks the new title up on its next title refresh.
"""

from __future__ import annotations

import asyncio
import re
import threading
import time
from typing import Callable

from config.settings import Settings
from core.client import LlamaClient
from sessions.store import SessionStore

_TITLE_INSTRUCTION = (
    "Write a 2-5 word title for this chat. Title Case, no quotes, no punctuation, "
    "no trailing period. Same language as the user. Output only the title."
)
# Prefilling a closed thinking channel keeps the model from generating a long
# reasoning trace for a 16-token title.
_NO_THINKING = "<|channel>Ok.<channel|>"

_FENCE = re.compile(r"^\s*```[a-zA-Z]*\s*|\s*```\s*$")
_JUNK = "\"'`*_#>“”‘’"


def clean_title(raw: str, fallback: str) -> str:
    """Normalize a model title, falling back to the user's own words."""
    text = _FENCE.sub("", (raw or "").strip()).strip()
    text = text.replace("\n", " ").replace("\r", " ")
    text = _FENCE.sub("", text).strip().strip(_JUNK).strip()
    text = re.sub(r"\s+", " ", text)
    text = text.rstrip(".,;:!?。，；：！？ ").strip().strip(_JUNK).strip()[:40].rstrip()
    if not text:
        text = " ".join((fallback or "").split())[:40].strip()
    return text or "New chat"


def _title_prompt(first_message: str, reply: str) -> str:
    user = " ".join(first_message.split())[:1000]
    assistant = " ".join(reply.split())[:300]
    return (
        f"<start_of_turn>system\n{_TITLE_INSTRUCTION}<end_of_turn>\n"
        f"<start_of_turn>user\nUser: {user}\nAssistant: {assistant}<end_of_turn>\n"
        f"<start_of_turn>model\n{_NO_THINKING}"
    )


async def generate_title(
    client: LlamaClient,
    first_message: str,
    reply: str = "",
    fallback: str | None = None,
) -> str:
    """One short, non-streaming local completion; never raises on bad output."""
    raw = await client.complete(
        _title_prompt(first_message, reply), n_predict=16, temperature=0.3
    )
    return clean_title(raw, fallback if fallback is not None else first_message)


async def suggest_title(client: LlamaClient, first_message: str, reply: str = "") -> str:
    """Backward-compatible wrapper used by the classic Textual TUI."""
    return await generate_title(client, first_message, reply)


class TitleManager:
    """Serialized background title worker shared by the chat and agent routes."""

    def __init__(
        self,
        store: SessionStore,
        settings: Settings,
        is_busy: Callable[[], bool],
    ) -> None:
        self.store = store
        self.settings = settings
        self.is_busy = is_busy
        self._pending: dict[str, tuple[float, int, str, str]] = {}
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._active = False
        self._drifted: set[str] = set()
        self._thread = threading.Thread(target=self._work, name="title-worker", daemon=True)
        self._thread.start()

    def busy(self) -> bool:
        return self._active

    def submit(
        self,
        session_id: str,
        first_message: str,
        reply: str,
        *,
        delay: float = 1.5,
        exchange: int = 1,
    ) -> None:
        """Queue a title; duplicate/older requests for a session are ignored."""
        if self.store.is_title_manual(session_id):
            return
        with self._lock:
            previous = self._pending.get(session_id)
            if previous and previous[1] > exchange:
                return
            self._pending[session_id] = (
                time.monotonic() + delay,
                exchange,
                first_message,
                reply,
            )

    def maybe_refresh_drift(self, session_id: str, exchange: int) -> None:
        """Optional one-shot retitle when a long chat changes topic."""
        if exchange < 3 or session_id in self._drifted:
            return
        first, _ = self.store.first_exchange(session_id)
        messages = self.store.messages(session_id)
        users = [str(m.get("content") or "") for m in messages if m.get("role") == "user"]
        if len(users) < 3:
            return
        before = set(re.findall(r"\w+", first.lower()))
        after = set(re.findall(r"\w+", " ".join(users[-2:]).lower()))
        if before and after and not (before & after):
            self._drifted.add(session_id)
            self.submit(
                session_id,
                after and users[-1] or first,
                "",
                delay=2.0,
                exchange=exchange,
            )

    def start_migration(self) -> None:
        """One-time, throttled pass over sessions with raw-message titles."""
        threading.Thread(target=self._migrate, name="title-migration", daemon=True).start()

    def _migrate(self) -> None:
        try:
            sessions = self.store.sessions_needing_titles()
        except Exception:  # noqa: BLE001 - migration is best effort
            return
        for index, session_id in enumerate(sessions):
            if self._stop.is_set():
                return
            first, reply = self.store.first_exchange(session_id)
            if first and reply:
                self.submit(session_id, first, reply, delay=5.0 + index * 20.0)

    def stop(self) -> None:
        self._stop.set()
        self._thread.join(timeout=2)

    def _work(self) -> None:
        while not self._stop.wait(0.5):
            now = time.monotonic()
            with self._lock:
                due = [(sid, item) for sid, item in self._pending.items() if item[0] <= now]
            for session_id, (ready_at, _exchange, first, reply) in due:
                if self._stop.is_set():
                    return
                if self.is_busy() or self._active:
                    with self._lock:
                        self._pending[session_id] = (now + 5.0, _exchange, first, reply)
                    continue
                with self._lock:
                    current = self._pending.get(session_id)
                    if not current or current[0] != ready_at:
                        continue
                    del self._pending[session_id]
                    self._active = True
                try:
                    title = asyncio.run(
                        generate_title(LlamaClient(self.settings), first, reply, first)
                    )
                    self.store.set_auto_title(session_id, title)
                except Exception:  # noqa: BLE001 - a title must never break chat
                    self.store.set_auto_title(session_id, clean_title("", first))
                finally:
                    self._active = False
